            return Continuous()
        elif var_type == "datetime":
            return Temporal()
        # TODO others
        # time-based (TimeStamp, TimeDelta, Period)
        # boolean scale?
        else:
            return Nominal()

    def infer_scale(self, arg: Any, data: Series) -> Scale:
